{"path":"index.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8" />
  <meta name="viewport" content="width=device-width,initial-scale=1" />
  <title>{{BUSINESS_NAME}} — {{TAGLINE}}</title>
  <meta name="description" content="Private practice therapy in {{CITY}}, {{STATE}} — compassionate, practical, evidence-informed care for anxiety, trauma, relationships, and major life transitions." />
  <link rel="stylesheet" href="assets/css/styles.css">
</head>
<body class="lux">
  <header class="site-header">
    <div class="wrap header-grid">
      <a class="brand" href="/"> 
        <svg class="logo" viewBox="0 0 100 30" xmlns="http://www.w3.org/2000/svg" aria-hidden="true">
          <rect x="0" y="0" width="100" height="30" rx="4" fill="#222" opacity="0.08" />
          <text x="8" y="20" font-family="sans-serif" font-size="12" fill="#111">{{BUSINESS_NAME}}</text>
        </svg>
      </a>
      <nav class="nav" id="primary-nav">
        <a href="/about.html">About</a>
        <a href="/specialties.html">Specialties</a>
        <a href="/approach.html">Approach</a>
        <a href="/fees.html">Fees</a>
        <a href="/book.html" class="btn small primary">{{PRIMARY_CTA_LABEL}}</a>
      </nav>
      <button id="mobile-toggle" class="nav-toggle" aria-label="Toggle navigation">☰</button>
    </div>
  </header>

  <main>
    <!-- HERO -->
    <section class="hero wrap gallery-hero" id="hero">
      <div class="hero-copy">
        <h1 class="eyebrow">Therapy for the life you want</h1>
        <h2 class="headline">I help adults in {{CITY}}, {{STATE}} move from stuck to steady with clear, compassionate guidance.</h2>
        <p class="lede">I combine trauma-informed care, practical coping skills, and collaborative planning so you can feel more present, connected, and in charge of your life. Sessions are confidential and grounded in ethical practice.</p>
        <div class="hero-ctas">
          <a class="btn primary" href="{{PRIMARY_CTA_URL}}">{{PRIMARY_CTA_LABEL}}</a>
          <a class="btn ghost" href="/contact.html">Contact</a>
        </div>
        <ul class="quick-list">
          <li>{{MODALITIES}}</li>
          <li>{{LICENSE}}</li>
          <li>Telehealth &amp; in-person</li>
        </ul>
      </div>
      <figure class="hero-art" aria-hidden="true">
        <img src="assets/img/hero.svg" alt="Abstract calm shapes" />
      </figure>
    </section>

    <!-- STORY -->
    <section class="wrap story" id="story">
      <div class="story-grid">
        <div class="avatar">
          <img src="assets/img/avatar.svg" alt="Portrait illustration of {{THERAPIST_NAME}}" />
        </div>
        <div class="story-copy">
          <h3>About {{THERAPIST_NAME}}</h3>
          <p>I’m {{THERAPIST_NAME}}, a licensed clinician practicing in {{CITY}}, {{STATE}}. I trained in short-term and relational therapies and have a focused interest in anxiety, trauma recovery, relationship repair, and life transition work. My style is warm, direct, and collaborative — we set clear goals and track progress together.</p>
          <p class="small">Confidentiality: Sessions are protected under standard clinical confidentiality. For emergencies or crisis situations, contact local emergency services or a crisis line — I do not provide crisis services via email or scheduling pages.</p>
        </div>
      </div>
    </section>

    <!-- FRAMEWORK -->
    <section class="wrap framework" id="framework">
      <header class="section-header">
        <h4>How I work — a simple, steady framework</h4>
        <p class="muted">A flexible process designed for clarity and momentum.</p>
      </header>
      <div class="grid three-up">
        <div class="card">
          <strong>Assessment &amp; Alliance</strong>
          <p>We map concerns, priorities, and immediate safety; together we form goals that feel meaningful and manageable.</p>
        </div>
        <div class="card">
          <strong>Skill Building</strong>
          <p>Practical tools (emotion regulation, grounding, communication) are taught and practiced between sessions.</p>
        </div>
        <div class="card">
          <strong>Integration &amp; Next Steps</strong>
          <p>We consolidate gains, plan for setbacks, and establish ongoing supports so changes hold over time.</p>
        </div>
      </div>
    </section>

    <!-- PROGRAMS -->
    <section class="wrap programs" id="programs">
      <header class="section-header">
        <h4>Available paths</h4>
        <p class="muted">Different formats depending on your goals and time.</p>
      </header>
      <div class="grid two-up">
        <div class="program">
          <h5>Clarity Path — 8-week focused plan</h5>
          <p>Structured weekly work for a targeted problem (e.g., anxiety, life transitions). Includes assessments and a written plan.</p>
          <a class="link" href="/approach.html">Learn more</a>
        </div>
        <div class="program">
          <h5>Foundations — Open weekly therapy</h5>
          <p>Ongoing weekly or biweekly sessions for broader work such as trauma integration, relationship repair, or long-term growth.</p>
          <a class="link" href="/specialties.html">See specialties</a>
        </div>
      </div>
    </section>

    <!-- PRICING -->
    <section class="wrap pricing" id="pricing">
      <header class="section-header">
        <h4>Fees &amp; insurance</h4>
        <p class="muted">Transparent options so you can plan ahead.</p>
      </header>
      <div class="grid three-up">
        <div class="price-card">
          <div class="price">$160</div>
          <div class="label">Standard 50-min session</div>
        </div>
        <div class="price-card">
          <div class="price">$120</div>
          <div class="label">25-min brief check-in</div>
        </div>
        <div class="price-card">
          <div class="price">Sliding Scale</div>
          <div class="label">Limited spots available — ask at intake</div>
        </div>
      </div>
      <p class="footnote">Insurance: I am a private-pay clinician. I can provide a superbill for potential insurance reimbursement. Session length, rates, and availability are subject to change.</p>
    </section>

    <!-- TESTIMONIALS -->
    <section class="wrap testimonials" id="testimonials">
      <header class="section-header">
        <h4>Client reflections</h4>
        <p class="muted">Names changed or withheld to protect confidentiality.</p>
      </header>
      <div class="grid two-up">
        <blockquote class="testimonial">
          "Practical, grounded work — I learned tools that actually fit my life. I feel more connected to my partner and calmer at work."
        </blockquote>
        <blockquote class="testimonial">
          "Warm and direct. I appreciated the clear plans and check-ins; I made steady progress when I had felt stuck for years."
        </blockquote>
      </div>
    </section>

    <!-- CTA -->
    <section class="wrap cta" id="cta">
      <div class="cta-grid">
        <div>
          <h4>Ready to start?</h4>
          <p>Schedule an introductory session to see if we’re a good fit. Sessions are confidential and ethically guided.</p>
        </div>
        <div class="cta-actions">
          <a class="btn large primary" href="{{PRIMARY_CTA_URL}}">{{PRIMARY_CTA_LABEL}}</a>
          <a class="btn ghost" href="/faq.html">Common questions</a>
        </div>
      </div>
    </section>
  </main>

  <footer class="site-footer">
    <div class="wrap footer-grid">
      <div>
        <strong>{{BUSINESS_NAME}}</strong>
        <address>{{CITY}}, {{STATE}} &bull; <a href="tel:{{PHONE}}">{{PHONE}}</a>
      </div>
      <div>
        <a href="/contact.html">Contact</a> &middot; <a href="/privacy.html">Privacy</a> &middot; <a href="/faq.html">FAQ</a>
      </div>
      <div class="license">
        <small>Licensed: {{LICENSE}}. Note: therapy is collaborative and there are no guarantees. If you are in crisis, contact emergency services immediately.</small>
      </div>
    </div>
  </footer>

  <script src="assets/js/main.js"></script>
</body>
</html>"} 
