{"path":"assets/css/styles.css","content":"/* Lux gallery theme - premium, spacious, restrained motion */
:root{
  --bg:#fbfbfb; --muted:#6b7280; --accent:#6b46c1; --accent-2:#3b82f6; --text:#0f172a; --card:#ffffff;
  --radius:12px; --max-width:1100px; --wrap-padding:24px;
}
*{box-sizing:border-box}
body{font-family:Inter, system-ui, -apple-system, 'Segoe UI', Roboto, 'Helvetica Neue', Arial; color:var(--text); background:var(--bg); margin:0; -webkit-font-smoothing:antialiased}
.wrap{max-width:var(--max-width); margin:0 auto; padding:36px var(--wrap-padding)}
.header-grid{display:flex; align-items:center; justify-content:space-between}
.brand{display:inline-flex; align-items:center; text-decoration:none; color:inherit}
.nav{display:flex; gap:18px; align-items:center}
.nav a{color:var(--text); text-decoration:none}
.btn{display:inline-block; padding:10px 16px; border-radius:10px; text-decoration:none}
.btn.primary{background:linear-gradient(135deg,var(--accent),var(--accent-2)); color:white}
.btn.ghost{background:transparent; border:1px solid rgba(15,23,42,0.06); color:var(--text)}
.btn.small{padding:8px 12px}
.nav-toggle{display:none; background:transparent; border:0; font-size:20px}

/* Hero */
.gallery-hero{display:grid; grid-template-columns:1fr 420px; gap:28px; align-items:center; padding-top:48px}
.hero-copy .eyebrow{font-size:14px; color:var(--muted); text-transform:uppercase; letter-spacing:1px}
.headline{font-size:32px; margin:8px 0 14px}
.lede{color:var(--muted); max-width:56ch}
.hero-ctas{margin-top:18px; display:flex; gap:12px}
.quick-list{display:flex; gap:12px; list-style:none; padding:0; margin-top:16px; color:var(--muted)}
.hero-art img{width:100%; height:auto; border-radius:18px; box-shadow:0 10px 30px rgba(12,18,28,0.06)}

/* Story */
.story-grid{display:grid; grid-template-columns:120px 1fr; gap:20px; align-items:center}
.avatar img{width:100%; border-radius:12px; background:linear-gradient(180deg,#fff,#f7f7fd)}
.story-copy h3{margin:0 0 8px}
.story-copy .small{font-size:12px; color:var(--muted)}

/* Framework */
.framework .three-up{display:grid; grid-template-columns:repeat(3,1fr); gap:18px}
.card{background:var(--card); padding:18px; border-radius:12px; box-shadow:0 8px 24px rgba(14,20,30,0.04)}

/* Programs */
.programs .two-up{display:grid; grid-template-columns:1fr 1fr; gap:18px}
.program{background:linear-gradient(180deg,#fff,#fcfbff); padding:18px; border-radius:12px}
.program h5{margin:0 0 6px}

/* Pricing */
.pricing .three-up{display:grid; grid-template-columns:repeat(3,1fr); gap:16px}
.price-card{background:var(--card); border-radius:12px; padding:18px; text-align:center}
.price{font-weight:700; font-size:20px}
.label{color:var(--muted)}

/* Testimonials */
.testimonials blockquote{background:#fff; padding:18px; border-radius:12px; color:var(--muted); box-shadow:0 6px 18px rgba(12,18,28,0.04)}

/* CTA */
.cta-grid{display:flex; justify-content:space-between; align-items:center; gap:18px}
.cta .large{padding:14px 20px; border-radius:14px}

/* Footer */
.site-footer{border-top:1px solid rgba(15,23,42,0.05); background:transparent}
.footer-grid{display:flex; justify-content:space-between; align-items:center; padding:18px 0}
.footer-grid a{color:var(--muted); text-decoration:none}
.license{max-width:360px; text-align:right}

/* Responsive */
@media(max-width:880px){
  .gallery-hero{grid-template-columns:1fr;}
  .header-grid{gap:12px}
  .nav{display:none}
  .nav-toggle{display:block}
  .story-grid{grid-template-columns:80px 1fr}
  .framework .three-up{grid-template-columns:1fr}
  .programs .two-up{grid-template-columns:1fr}
  .pricing .three-up{grid-template-columns:1fr}
  .cta-grid{flex-direction:column; align-items:flex-start}
}

/* subtle motion */
.hero-art img{transform:translateY(0); transition:transform 600ms ease}
.hero-art img:hover{transform:translateY(-6px)}
"} 
{"path":"assets/js/main.js","content":"document.addEventListener('DOMContentLoaded', function(){
  var toggle = document.getElementById('mobile-toggle');
  var nav = document.getElementById('primary-nav');
  toggle && toggle.addEventListener('click', function(){
    if(nav.style.display==='flex'){ nav.style.display='none'; }
    else{ nav.style.display='flex'; nav.style.flexDirection='column'; nav.style.gap='12px'; }
  });

  // Smooth internal links
  document.querySelectorAll('a[href^="#"]').forEach(function(a){
    a.addEventListener('click', function(e){
      e.preventDefault(); document.querySelector(a.getAttribute('href')).scrollIntoView({behavior:'smooth'});
    });
  });

  // Basic accessibility: focus visible outline for keyboard navigation
  document.body.addEventListener('keydown', function(e){
    if(e.key==='Tab'){ document.documentElement.classList.add('show-focus'); }
  });

  // Replace tel placeholder formatting if needed
  // Minimal form behavior (if a booking link opens a modal, keep simple redirect)
  var ctas = document.querySelectorAll('a[href$="/book.html"], a[href*="book.html"], a[href*="{{PRIMARY_CTA_URL}}"]');
  ctas.forEach(function(cta){
    cta.addEventListener('click', function(e){
      // allow default navigation — could be replaced with an overlay booking flow
    });
  });
});"} 
